Papers.AnsariRockel2024.galambos_cdf_ful.type:
∀ (δ : ℝ) (hδ : 0 < δ) (u : Fin 2 → ↑unitInterval),
  (Verification.galambos δ hδ).cdf u =
    if u 0 = 0 ∨ u 1 = 0 then 0
    else
      if u 0 = 1 then ↑(u 1)
      else
        if u 1 = 1 then ↑(u 0)
        else ↑(u 0) * ↑(u 1) * Real.exp (((-Real.log ↑(u 0)) ^ (-δ) + (-Real.log ↑(u 1)) ^ (-δ)) ^ (-1 / δ))

Papers.AnsariRockel2024.gumbel_cdf_full.type:
∀ (θ : ℝ) (hθ : 1 ≤ θ) (u v : ↑unitInterval),
  (ProbabilityTheory.Copula.gumbel θ hθ).cdf ![u, v] =
    if u = 0 ∨ v = 0 then 0 else Real.exp (-((-Real.log ↑u) ^ θ + (-Real.log ↑v) ^ θ) ^ θ⁻¹)

Papers.AnsariRockel2024.laplace_spearman.type:
∀ (r : ℝ) (hr : r ∈ Set.Icc (-1) 1),
  have μ := ProbabilityTheory.gammaProbability 1 1 ⋯ ⋯;
  have W := fun t => √t ^ 2;
  (Verification.laplaceBivariate r hr).spearmanRho =
    6 / Real.pi *
      ∫ (a : ℝ), ∫ (t : ℝ × ℝ), Real.arcsin (r * Papers.AnsariRockel2024.hvV (W t.1) (W t.2) (W a)) ∂(↑μ).prod ↑μ ∂↑μ

Papers.AnsariRockel2024.nelsen13_cdf.type:
∀ (θ : ℝ) (hθ : 0 < θ) (u v : ↑unitInterval),
  (Verification.nelsen13 θ ⋯).cdf ![u, v] =
    if u = 0 ∨ v = 0 then 0 else Real.exp (1 - ((1 - Real.log ↑u) ^ θ + (1 - Real.log ↑v) ^ θ - 1) ^ θ⁻¹)

Papers.AnsariRockel2024.nelsen14_cdf_ful.type:
∀ (θ : ℝ) (hθ : 1 ≤ θ) (u v : ↑unitInterval),
  (ProbabilityTheory.Copula.nelsen14 θ hθ).cdf ![u, v] =
    if u = 0 ∨ v = 0 then 0 else (1 + ((↑u ^ (-θ⁻¹) - 1) ^ θ + (↑v ^ (-θ⁻¹) - 1) ^ θ) ^ θ⁻¹) ^ (-θ)

Papers.AnsariRockel2024.nelsen19_cdf.type:
∀ {θ : ℝ} (hθ : 0 < θ) (u v : ↑unitInterval),
  (Verification.nelsen19 θ ⋯).cdf ![u, v] =
    if u = 0 ∨ v = 0 then 0 else θ / Real.log (Real.exp (θ / ↑u) + Real.exp (θ / ↑v) - Real.exp θ)

Papers.AnsariRockel2024.nelsen20_cdf.type:
∀ {θ : ℝ} (hθ : 0 < θ) (u v : ↑unitInterval),
  (Verification.nelsen20 θ ⋯).cdf ![u, v] =
    if u = 0 ∨ v = 0 then 0 else Real.log (Real.exp (↑u ^ (-θ)) + Real.exp (↑v ^ (-θ)) - Real.exp 1) ^ (-θ⁻¹)

Papers.AnsariRockel2024.nelsen2_cdf_full.type:
∀ (θ : ℝ) (hθ : 1 ≤ θ) (u v : ↑unitInterval),
  (ProbabilityTheory.Copula.nelsen2 θ hθ).cdf ![u, v] =
    if u = 0 ∨ v = 0 then 0 else Max.max 0 (1 - ((1 - ↑u) ^ θ + (1 - ↑v) ^ θ) ^ θ⁻¹)

Papers.AnsariRockel2024.student_spearman.type:
∀ (r : ℝ) (hr : r ∈ Set.Icc (-1) 1) (ν : ℝ) (hν : 0 < ν),
  have μ := ProbabilityTheory.gammaProbability (ν / 2) (ν / 2) ⋯ ⋯;
  have W := fun t => (√t)⁻¹ ^ 2;
  (Verification.studentBivariate r hr ν hν).spearmanRho =
    6 / Real.pi *
      ∫ (a : ℝ), ∫ (t : ℝ × ℝ), Real.arcsin (r * Papers.AnsariRockel2024.hvV (W t.1) (W t.2) (W a)) ∂(↑μ).prod ↑μ ∂↑μ
